namespace InventoryApp.Services;

public record EquipmentItem(int Id, string Name, string Location, DateTime LastInspected);

public interface IEquipmentService
{
    Task<List<EquipmentItem>> GetEquipmentAsync();
}

public class EquipmentService : IEquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate a slow data source
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new(1, "Forklift A",        "Warehouse 1",  new DateTime(2026, 6, 10)),
            new(2, "Conveyor Belt B",    "Warehouse 2",  new DateTime(2026, 5, 22)),
            new(3, "Pallet Jack C",      "Dock 3",       new DateTime(2026, 7, 1)),
            new(4, "Crane D",            "Yard North",   new DateTime(2026, 4, 15)),
            new(5, "Drill Press E",      "Shop Floor",   new DateTime(2026, 3, 30)),
            new(6, "Lathe F",            "Shop Floor",   new DateTime(2026, 6, 28)),
            new(7, "Welding Rig G",      "Bay 4",        new DateTime(2026, 7, 8)),
            new(8, "Compressor H",       "Utility Room", new DateTime(2026, 2, 14)),
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@using InventoryApp.Services
@inject IEquipmentService EquipmentService
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_equipment is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _equipment)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? _equipment;
    private PersistingComponentStateSubscription _persistingSubscription;

    protected override async Task OnInitializedAsync()
    {
        _persistingSubscription = ApplicationState.RegisterOnPersisting(PersistEquipment);

        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>(
                nameof(_equipment), out var restored))
        {
            _equipment = restored;
        }
        else
        {
            _equipment = await EquipmentService.GetEquipmentAsync();
        }
    }

    private Task PersistEquipment()
    {
        ApplicationState.PersistAsJson(nameof(_equipment), _equipment);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _persistingSubscription.Dispose();
    }
}

